package net.civeira.phylax.features.notification.message.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.tenant.domain.TenantReference;

class MessageChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_message_change_set_builder() {
    MessageChangeSet one = new MessageChangeSet().uid("one").target("one")
        .tenant(TenantReference.of("one")).content("one").retries(1)
        .createdAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .sendAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getTarget().get(), "Value must equals to the intial value");
    one.target("two");
    Assertions.assertEquals("two", one.getTarget().get(),
        "Value must equals to the assigned value");
    one.unset("target");
    Assertions.assertFalse(one.getTarget().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(TenantReference.of("one"), one.getTenant().get(),
        "Value must equals to the intial value");
    one.tenant(TenantReference.of("two"));
    Assertions.assertEquals(TenantReference.of("two"), one.getTenant().get(),
        "Value must equals to the assigned value");
    one.unset("tenant");
    Assertions.assertFalse(one.getTenant().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getContent().get(), "Value must equals to the intial value");
    one.content("two");
    Assertions.assertEquals("two", one.getContent().get(),
        "Value must equals to the assigned value");
    one.unset("content");
    Assertions.assertFalse(one.getContent().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getRetries().get(), "Value must equals to the intial value");
    one.retries(2);
    Assertions.assertEquals(2, one.getRetries().get(), "Value must equals to the assigned value");
    one.unset("retries");
    Assertions.assertFalse(one.getRetries().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getCreatedAt().get(), "Value must equals to the intial value");
    one.createdAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getCreatedAt().get(), "Value must equals to the assigned value");
    one.unset("createdAt");
    Assertions.assertFalse(one.getCreatedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getSendAt().get(), "Value must equals to the intial value");
    one.sendAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getSendAt().get(), "Value must equals to the assigned value");
    one.unset("sendAt");
    Assertions.assertFalse(one.getSendAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
